def rules(fan_in, fan_out):
    target = (fan_out / fan_in) ** 0.5                 # spectral norm goal
    init_std = target / (fan_in ** 0.5 + fan_out ** 0.5)
    adam_lr = target / (fan_in * fan_out) ** 0.5       # entries +-lr, rank one
    sgd_lr = fan_out / fan_in                          # needs |grad| ~ 1/target
    return init_std, adam_lr, sgd_lr

