def is_hidden(name, p):          # matrix-like: both dims grow with width
    return p.ndim == 2 and not name.startswith(("emb", "unemb"))

def init_(model, sigma):
    for name, p in model.named_parameters():
        if p.ndim == 2:          # emb, unemb: std sigma; hidden: std sigma / sqrt(m)
            std = sigma / math.sqrt(model.m) if is_hidden(name, p) else sigma
            nn.init.normal_(p, 0.0, std)
        elif name.endswith("bias"):
            nn.init.zeros_(p)    # LayerNorm gains keep their default 1

def param_groups(model, lr, wd):
    hid = [p for n, p in model.named_parameters() if is_hidden(n, p)]
    vec = [p for n, p in model.named_parameters() if not is_hidden(n, p)]
    return [{"params": hid, "lr": lr / model.m, "weight_decay": wd * model.m},
            {"params": vec, "lr": lr, "weight_decay": wd}]

